cd /user/user1/autorlbench-runs/20261121162153-52866-1f1e/workspace; python3 -I -c "
import json,pyarrow.parquet as pq,collections
for name,src in [('train','data_evidence/train.jsonl'),('val','data_evidence/val.jsonl')]:
    js=[json.loads(l) for l in open(src)]
    pqrows=pq.read_table(f'data/{name}.parquet').to_pylist()
    print(name,'jsonl',len(js),'parquet',len(pqrows))
    # compare as sorted json
    def key(r): return (r['extra_info']['occurrence_id'], r['extra_info']['scenario_id'])
    jkeys=[key(r) for r in js]; pkeys=[key(r) for r in pqrows]
    print(' same keys set', set(jkeys)==set(pkeys), 'dupe jsonl',len(jkeys)-len(set(jkeys)),'dupe pq',len(pkeys)-len(set(pkeys)))
    # compare prompt content
    jd={key(r):json.dumps(r,sort_keys=True) for r in js}; pd={key(r):json.dumps(r,sort_keys=True) for r in pqrows}
    diff=[k for k in jd if k in pd and jd[k]!=pd[k]]
    print(' differing rows',len(diff))
    if diff:
        k=diff[0]
        a=json.loads(jd[k]); b=json.loads(pd[k])
        for f in a:
            if a[f]!=b.get(f): print('  field',f,'jsonl',str(a[f])[:200],'pq',str(b.get(f))[:200])
"

